import os
import re

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Values for these keys are never printed in full (see payhook/doctor.py).
SECRET_KEYS = frozenset({"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"})

_EXPORT_PREFIX = re.compile(r"^export\s+")
_INLINE_COMMENT = re.compile(r"\s#")


def _parse_quoted(raw, quote):
    """Return the contents of a quoted value, or None if it is not properly quoted."""
    body = []
    i = 1
    while i < len(raw):
        ch = raw[i]
        if quote == '"' and ch == "\\" and i + 1 < len(raw) and raw[i + 1] in '"\\':
            body.append(raw[i + 1])
            i += 2
            continue
        if ch == quote:
            rest = raw[i + 1:].strip()
            if rest and not rest.startswith("#"):
                return None
            return "".join(body)
        body.append(ch)
        i += 1
    return None


def _parse_value(raw):
    raw = raw.strip()
    if raw[:1] in ("'", '"'):
        quoted = _parse_quoted(raw, raw[0])
        if quoted is not None:
            return quoted
    # Unquoted: a " #" starts a comment.
    match = _INLINE_COMMENT.search(raw)
    if match:
        raw = raw[:match.start()]
    return raw.strip()


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            key, sep, value = line.partition("=")
            if not sep:
                continue
            key = _EXPORT_PREFIX.sub("", key.strip(), count=1).strip()
            if not key:
                continue
            values[key] = _parse_value(value)
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config

